package io.aetheris.orchestrator.api;
import io.aetheris.orchestrator.ingestion.*;import io.aetheris.orchestrator.memory.*;import io.aetheris.orchestrator.stage9.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/orchestrator/stage9") public class Stage9CoreController {private final AdaptiveLocalEmbeddingAdapter embeddings;private final Stage9AdaptiveVectorIndexService adaptiveVectors;private final IncrementalKnowledgeIngestionService ingestion;private final BenchmarkService benchmarks;private final MissionDryRunService dryRuns;private final CapabilityAwareDispatchService dispatch;public Stage9CoreController(AdaptiveLocalEmbeddingAdapter embeddings,Stage9AdaptiveVectorIndexService adaptiveVectors,IncrementalKnowledgeIngestionService ingestion,BenchmarkService benchmarks,MissionDryRunService dryRuns,CapabilityAwareDispatchService dispatch){this.embeddings=embeddings;this.adaptiveVectors=adaptiveVectors;this.ingestion=ingestion;this.benchmarks=benchmarks;this.dryRuns=dryRuns;this.dispatch=dispatch;}@GetMapping("/embedding/runtime") public EmbeddingRuntimeSnapshot embedding(){return embeddings.runtime();}@PostMapping("/embedding/rebuild") public Map<String,Object> rebuild(){return Map.of("indexed",adaptiveVectors.rebuild(),"adapter",embeddings.id());}@GetMapping("/memory/search") public List<VectorMemorySearchResult> search(@RequestParam String q,@RequestParam(required=false) MemoryScope scope,@RequestParam(required=false) String namespace,@RequestParam(defaultValue="false") boolean includeProtected,@RequestParam(defaultValue="10") int limit){return adaptiveVectors.search(q,scope,namespace,includeProtected,limit);}@PostMapping("/ingestion/sync") public IncrementalIngestionResult sync(@RequestBody IngestKnowledgeRequest r){return ingestion.sync(r);}@PostMapping("/ingestion/tombstone") public IncrementalIngestionResult tombstone(@RequestParam String kind,@RequestParam String sourceId,@RequestParam String namespace){return ingestion.tombstone(kind,sourceId,namespace);}@GetMapping("/ingestion/sources") public List<IngestionSourceStateEntity> sources(){return ingestion.recent();}@GetMapping("/benchmarks") public List<BenchmarkPack> packs(){return benchmarks.packs();}@PostMapping("/benchmarks/run") public BenchmarkRunResult benchmark(@RequestBody BenchmarkRunRequest r){return benchmarks.record(r);}@PostMapping("/missions/dry-run") public MissionDryRunResult dryRun(@RequestBody MissionDryRunRequest r){return dryRuns.evaluate(r);}@PutMapping("/workers/{workerId}/capabilities") public WorkerCapabilityEntity worker(@PathVariable String workerId,@RequestBody WorkerCapabilityRequest r){return dispatch.setWorker(workerId,r);}@PutMapping("/work/{workItemId}/requirements") public WorkRequirementEntity requirement(@PathVariable UUID workItemId,@RequestBody WorkRequirementRequest r){return dispatch.setRequirement(workItemId,r);}@GetMapping("/workers/capabilities") public List<WorkerCapabilityEntity> workers(){return dispatch.workers();}@PostMapping("/dispatch") public CapabilityDispatchResult dispatch(@RequestParam(defaultValue="60") int leaseSeconds){return dispatch.dispatch(leaseSeconds);}}
